package android.os;
import java.util.*;
public class Handler{static long now=0,seq=0;static class Task{Handler owner;Runnable action;long at,order;Task(Handler h,Runnable r,long t){owner=h;action=r;at=t;order=seq++;}}static final ArrayList<Task> tasks=new ArrayList<>();public Handler(Looper l){}public boolean post(Runnable r){return postDelayed(r,0);}public boolean postDelayed(Runnable r,long delay){synchronized(tasks){tasks.add(new Task(this,r,now+delay));}return true;}public void removeCallbacksAndMessages(Object token){synchronized(tasks){tasks.removeIf(t->t.owner==this);}}public static void drain(){for(int i=0;i<10000;i++){Task task=null;synchronized(tasks){tasks.sort(Comparator.<Task>comparingLong(t->t.at).thenComparingLong(t->t.order));if(!tasks.isEmpty()&&tasks.get(0).at<=now)task=tasks.remove(0);}if(task==null)return;task.action.run();}throw new AssertionError("Handler did not quiesce");}public static void advance(long ms){now+=ms;drain();}}
